property.value:
let $tokens := function($n) {
      tokenize(lower-case(replace(replace($n, '([a-z0-9])([A-Z])', '$1 $2'), '_', ' ')), ' +')[. != '']
    },
    $isEquality := function($e) {
      exists($e/self::MethodCall[@MethodName = ('equals', 'deepEquals', 'equalLists', 'equalsIgnoreCase')]
               [ArgumentList/@Size = (1, 2)])
      or exists($e/self::InfixExpression[@Operator = '=='][count(*) = 2]
                  [empty(*[self::NullLiteral or self::BooleanLiteral or self::NumericLiteral or self::StringLiteral
                           or self::CharLiteral or matches(@Name, '(^|\.)[A-Z][A-Z0-9_]*$')])])
    },
    $changeWords := ('changed', 'modified', 'dirty', 'different', 'differs', 'updated', 'diff', 'changes'),
    $negations := ('not', 'unchanged', 'unmodified', 'same', 'equal', 'equals', 'identical', 'matches', 'match', 'clean')
return (
//MethodDeclaration
  [matches(@Name, '^(is|has|was|needs)([A-Z][a-z0-9]*)*(Modified|Changed|Changes|Dirty|Different|Updated|Diff)$')]
  [empty($tokens(@Name)[. = $negations])]
  [Block[@Size = 1]/ReturnStatement[$isEquality(*[1])]]
|
//VariableDeclarator
  [let $words := $tokens(VariableId/@Name)
   return exists(parent::LocalVariableDeclaration[empty(PrimitiveType | ClassType) or PrimitiveType[@Kind = 'boolean'] or ClassType[@SimpleName = 'Boolean']])
     and $words[last()] = $changeWords and empty($words[. = $negations])
     and $isEquality(*[2])]
|
//AssignmentExpression[@Operator = '='][*[1][self::VariableAccess or (self::FieldAccess and *[1][self::ThisExpression])]]
  [let $words := $tokens(*[1]/@Name)
   return $words[last()] = $changeWords and empty($words[. = $negations]) and $isEquality(*[2])]
)
